import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"恆","description":"周易集解 - 恆","frontmatter":{"title":"恆","description":"周易集解 - 恆"},"headers":[],"relativePath":"zh/classics/jijie/032.md","filePath":"zh/classics/jijie/032.md"}'),l={name:"zh/classics/jijie/032.md"};function n(d,a,p,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="恆" tabindex="-1">恆 <a class="header-anchor" href="#恆" aria-label="Permalink to “恆”">​</a></h1><h2 id="恆-1" tabindex="-1">恆 <a class="header-anchor" href="#恆-1" aria-label="Permalink to “恆”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>恆，亨，無咎，利貞。利有攸往。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《序卦》曰：夫婦之道，不可不久也。故受之以恆。恆者，久也。</p><p>鄭玄曰：言夫婦當有終身之義。夫婦之道，謂咸者也。</p><p>虞翻曰：恆，久也。與益旁通。乾初之坤四，剛柔皆應，故通，無咎，利貞矣。</p><p>鄭玄曰：恆，久也。巽為風，震為雷，雷風相須而養物，猶長女承長男，夫婦同心而成家，久長之道也。夫婦以嘉會禮通，故無咎。其能和順幹事，所行而善矣。</p><p>虞翻曰：初利往之四，終變成益，則初四二五皆得其正，終則有始，故利有攸往也。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：恆，久也。剛上而柔下，雷風相與，巽而動，剛柔皆應，恆。恆亨，無咎，利貞，久於其道也。天地之道，恆久而不已也。利有攸往，終則有始也。日月得天而能久照，四時變化而能久成。聖人久於其道，而天下化成。觀其所恆，而天地萬物之情可見矣。</p><h2 id="彖传注" tabindex="-1">彖传注 <a class="header-anchor" href="#彖传注" aria-label="Permalink to “彖传注”">​</a></h2><p>王弼曰：剛尊柔卑，得其序也。</p><p>蜀才曰：此本泰卦。</p><p>案：六四降初，初九升四，是剛上而柔下也。分乾與坤，雷也。分坤與乾，風也。是雷風相與，巽而動也。</p><p>《九家易》曰：初四二五雖不正，而剛柔皆應，故通無咎矣。</p><p>荀爽曰：恆，震世也，巽來乘之，陰陽合會，故通無咎。長男在上，長女在下，夫婦道正，故利貞，久於其道也。</p><p>虞翻曰：泰，乾坤為天地。謂終則復始，有親則可久也。</p><p>荀爽曰：謂乾氣下終，始復升上居四也。坤氣上終，始復降下居初者也。</p><p>虞翻曰：動初，成乾為天。至二，離為日；至三，坎為月。故日月得天而能久照也。</p><p>虞翻曰：春夏為變，秋冬為化，變至二離夏，至三兌秋，至四震春，至五坎冬。故四時變化而能久成。謂乾坤成物也。</p><p>虞翻曰：聖人謂乾。乾為道。初二已正，四五複位，成既濟定。乾道變化，各正性命。有兩離象，重明麗正，故化成天下。</p><p>虞翻曰：以離日照乾，坎月照坤，萬物出震，故天地萬物之情可見矣。與咸同義也。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：雷風，恆。君子以立不易方。</p><h2 id="象传注" tabindex="-1">象传注 <a class="header-anchor" href="#象传注" aria-label="Permalink to “象传注”">​</a></h2><p>宋衷曰：雷以動之，風以散之。二者常相薄，而為萬物用，故君子象之，以立身守節而不易道也。</p><p>虞翻曰：君子謂乾三也。乾為易，為立；坤為方。乾初之坤四，三正不動。故立不易方也。</p><h2 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h2><p>初六，浚恆，貞凶，無攸利。</p><h2 id="初六注" tabindex="-1">初六注 <a class="header-anchor" href="#初六注" aria-label="Permalink to “初六注”">​</a></h2><p>侯果曰：浚，深。恆，久也。初本六四，自四居初，始求深厚之位者也。位既非正，求乃涉邪。以此為正，凶之道也。故曰｢浚恆，貞凶，無攸利｣矣。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：浚恆之凶，始求深也。</p><h2 id="象传注-1" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-1" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：浚，深也。初下稱浚，故曰浚恆。乾初為淵，故深矣。失位變之正，乾為始。故曰始求深也。</p><h2 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h2><p>九二，悔亡。</p><h2 id="九二注" tabindex="-1">九二注 <a class="header-anchor" href="#九二注" aria-label="Permalink to “九二注”">​</a></h2><p>虞翻曰：失位悔也，動而得正，處中多譽，故悔亡也。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：九二悔亡，能久中也。</p><h2 id="象传注-2" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-2" aria-label="Permalink to “象传注”">​</a></h2><p>荀爽曰：乾為久也。能久行中和，以陽據陰，故曰能久中也。</p><h2 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h2><p>九三，不恆其德，或承之羞，貞吝。</p><h2 id="九三注" tabindex="-1">九三注 <a class="header-anchor" href="#九三注" aria-label="Permalink to “九三注”">​</a></h2><p>荀爽曰：與初同象，欲據初，隔二。與五為兌，欲悅之，隔四。意無所定，故不恆其德。與上相應，欲往承之，為陰所乘，故或承之羞也。貞吝者，謂正乘其所，不與陰通也。無居自容，故貞吝矣。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：不恆其德，無所容也。</p><h2 id="象传注-3" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-3" aria-label="Permalink to “象传注”">​</a></h2><p>《九家易》曰：言三取初隔二，應上見乘，是無所容。無居自容，故貞吝。</p><h2 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h2><p>九四，田無禽。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：久非其位，安得禽也。</p><h2 id="象传注-4" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-4" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：田為二。二地上，稱田，無禽，為五也。九四失位，利也上之五，已變承之。故曰田無禽。言二五皆非其位，故《象》曰：｢久非其位，安得禽也。｣</p><h2 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h2><p>六五，恆其德，貞，婦人吉，夫子凶。</p><h2 id="六五注" tabindex="-1">六五注 <a class="header-anchor" href="#六五注" aria-label="Permalink to “六五注”">​</a></h2><p>虞翻曰：動正成乾，故恆其德。婦人謂初。巽為婦。終變成益，震四復初，婦得歸陽，從一而終，故貞婦人吉也。震，乾之子，而為巽夫，故曰夫子。終變成益，震四從巽，死於坤中，故夫子凶也。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：婦人貞吉，從一而終也。夫子制義，從婦凶也。</p><h2 id="象传注-5" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-5" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：一謂初，終變成益，以巽應初震，故從一而終也。</p><p>虞翻曰：震沒從巽入坤，故從婦凶矣。</p><h2 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h2><p>上六，震恆，凶。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：震恆在上，大無功也。</p><h2 id="象传注-6" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-6" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：在震上，故震恆。五動乘陽，故凶。終在益上，五遠應，故無功也。</p>',74)])])}const f=e(l,[["render",n]]);export{b as __pageData,f as default};
